5	enum NinebotPushError: LocalizedError {
6	    case denied
7	    case missingToken
8	    case missingBundleID
9	    case missingServer
10	
11	    var errorDescription: String? {
12	        switch self {
13	        case .denied:
14	            return "系统通知权限未开启"
15	        case .missingToken:
16	            return "还没有拿到 APNs 设备 Token，请稍后再试"
17	        case .missingBundleID:
18	            return "无法读取 App Bundle ID"
19	        case .missingServer:
20	            return "请先填写 NinePlus 平台地址和 Token"
21	        }
22	    }
23	}
