25	final class NinebotPushManager: NSObject, UIApplicationDelegate, UNUserNotificationCenterDelegate {
26	    static let shared = NinebotPushManager()
27	
28	    private let store = NinebotSharedStore()
29	
30	    func application(
31	        _ application: UIApplication,
32	        didFinishLaunchingWithOptions launchOptions: [UIApplication.LaunchOptionsKey: Any]? = nil
33	    ) -> Bool {
34	        UNUserNotificationCenter.current().delegate = self
35	        NinebotChargingLiveActivityManager.startRemoteTokenObservation()
36	        Task { await requestAuthorizationOnLaunchAndRegister() }
37	        return true
38	    }
39	
40	    func application(
41	        _ application: UIApplication,
42	        didRegisterForRemoteNotificationsWithDeviceToken deviceToken: Data
43	    ) {
44	        let token = deviceToken.map { String(format: "%02x", $0) }.joined()
45	        store.savePushDeviceToken(token)
46	        Task {
47	            try? await registerStoredTokenWithServer()
48	            try? await registerStoredLiveActivityTokensWithServer()
49	        }
50	    }
51	
52	    func application(
53	        _ application: UIApplication,
54	        didFailToRegisterForRemoteNotificationsWithError error: Error
55	    ) {
56	        // Registration can fail on simulator or when signing lacks Push Notifications.
57	    }
58	
59	    func userNotificationCenter(
60	        _ center: UNUserNotificationCenter,
61	        willPresent notification: UNNotification
62	    ) async -> UNNotificationPresentationOptions {
63	        [.banner, .sound, .badge]
64	    }
65	
66	    func requestAuthorizationAndRegister() async throws {
67	        let granted = try await requestAuthorization()
68	        guard granted else { throw NinebotPushError.denied }
69	        registerForRemoteNotifications()
70	        try? await registerStoredLiveActivityTokensWithServer()
71	    }
72	
73	    func requestAuthorizationRegisterAndWaitForToken() async throws -> String? {
74	        let granted = try await requestAuthorization()
75	        guard granted else { throw NinebotPushError.denied }
76	        registerForRemoteNotifications()
77	        try? await registerStoredLiveActivityTokensWithServer()
78	        return await waitForStoredToken()
79	    }
80	
81	    func registerStoredTokenWithServer() async throws {
82	        guard let token = store.loadPushDeviceToken() else {
83	            throw NinebotPushError.missingToken
84	        }
85	        guard let bundleID = Bundle.main.bundleIdentifier, !bundleID.isEmpty else {
86	            throw NinebotPushError.missingBundleID
87	        }
88	        guard let configuration = store.loadConfiguration(), configuration.isUsable else {
89	            throw NinebotPushError.missingServer
90	        }
91	        try await NinebotServerClient(configuration: configuration).registerPushDevice(
92	            token: token,
93	            bundleID: bundleID,
94	            environment: Self.apnsEnvironment
95	        )
96	    }
97	
98	    func registerStoredLiveActivityTokensWithServer() async throws {
99	        var firstError: Error?
100	
101	        if let pushToStartToken = store.loadChargingLiveActivityPushToStartToken() {
102	            do {
103	                try await registerLiveActivityTokenWithServer(
104	                    token: pushToStartToken,
105	                    tokenKind: "push_to_start",
106	                    activityID: nil,
107	                    vehicleSN: nil
108	                )
109	            } catch {
110	                firstError = error
111	            }
112	        }
113	
114	        for record in store.loadChargingLiveActivityPushTokenRecords() {
115	            do {
116	                try await registerLiveActivityTokenWithServer(
117	                    token: record.token,
118	                    tokenKind: "activity",
119	                    activityID: record.activityID,
120	                    vehicleSN: record.vehicleSN
121	                )
122	            } catch {
123	                if firstError == nil {
124	                    firstError = error
125	                }
126	            }
127	        }
128	
129	        if let firstError {
130	            throw firstError
131	        }
132	    }
133	
134	    func registerLiveActivityPushTokenWithServer(token: String, activityID: String, vehicleSN: String) async throws {
135	        store.saveChargingLiveActivityPushToken(token, activityID: activityID, vehicleSN: vehicleSN)
136	        try await registerLiveActivityTokenWithServer(
137	            token: token,
138	            tokenKind: "activity",
139	            activityID: activityID,
140	            vehicleSN: vehicleSN
141	        )
142	    }
143	
144	    private func requestAuthorizationOnLaunchAndRegister() async {
145	        let settings = await notificationSettings()
146	        switch settings.authorizationStatus {
147	        case .notDetermined:
148	            guard ((try? await requestAuthorization()) ?? false) else { return }
149	            registerForRemoteNotifications()
150	            try? await registerStoredLiveActivityTokensWithServer()
151	        case .authorized, .provisional, .ephemeral:
152	            registerForRemoteNotifications()
153	            try? await registerStoredLiveActivityTokensWithServer()
154	        default:
155	            break
156	        }
157	    }
158	
159	    @MainActor
160	    private func registerForRemoteNotifications() {
161	        UIApplication.shared.registerForRemoteNotifications()
162	    }
163	
164	    private func requestAuthorization() async throws -> Bool {
165	        try await withCheckedThrowingContinuation { continuation in
166	            UNUserNotificationCenter.current().requestAuthorization(options: [.alert, .badge, .sound]) { granted, error in
167	                if let error {
168	                    continuation.resume(throwing: error)
169	                } else {
170	                    continuation.resume(returning: granted)
171	                }
172	            }
173	        }
174	    }
175	
176	    private func waitForStoredToken() async -> String? {
177	        if let token = store.loadPushDeviceToken() {
178	            return token
179	        }
180	
181	        for _ in 0..<20 {
182	            try? await Task.sleep(nanoseconds: 100_000_000)
183	            if let token = store.loadPushDeviceToken() {
184	                return token
185	            }
186	        }
187	
188	        return store.loadPushDeviceToken()
189	    }
190	
191	    private func registerLiveActivityTokenWithServer(
192	        token: String,
193	        tokenKind: String,
194	        activityID: String?,
195	        vehicleSN: String?
196	    ) async throws {
197	        guard let bundleID = Bundle.main.bundleIdentifier, !bundleID.isEmpty else {
198	            throw NinebotPushError.missingBundleID
199	        }
200	        guard let configuration = store.loadConfiguration(), configuration.isUsable else {
201	            throw NinebotPushError.missingServer
202	        }
203	        try await NinebotServerClient(configuration: configuration).registerLiveActivityToken(
204	            token: token,
205	            tokenKind: tokenKind,
206	            bundleID: bundleID,
207	            environment: Self.apnsEnvironment,
208	            deviceToken: store.loadPushDeviceToken(),
209	            activityID: activityID,
210	            vehicleSN: vehicleSN
211	        )
212	    }
213	
214	    private func notificationSettings() async -> UNNotificationSettings {
215	        await withCheckedContinuation { continuation in
216	            UNUserNotificationCenter.current().getNotificationSettings { settings in
217	                continuation.resume(returning: settings)
218	            }
219	        }
220	    }
221	
222	    private static var apnsEnvironment: String {
223	        if let provisioningEnvironment = Bundle.main.ninebotAPNsEnvironment {
224	            return provisioningEnvironment
225	        }
226	        #if DEBUG
227	        return "development"
228	        #else
229	        return "production"
230	        #endif
231	    }
232	}
233	
234	private extension Bundle {
235	    var ninebotAPNsEnvironment: String? {
236	        guard let url = url(forResource: "embedded", withExtension: "mobileprovision"),
237	              let data = try? Data(contentsOf: url),
238	              let profile = String(data: data, encoding: .isoLatin1) ?? String(data: data, encoding: .utf8),
239	              let keyRange = profile.range(of: "<key>aps-environment</key>") else {
240	            return nil
241	        }
242	
243	        let tail = profile[keyRange.upperBound...]
244	        guard let valueStart = tail.range(of: "<string>"),
245	              let valueEnd = tail[valueStart.upperBound...].range(of: "</string>") else {
246	            return nil
247	        }
248	
249	        let value = tail[valueStart.upperBound..<valueEnd.lowerBound]
250	            .trimmingCharacters(in: .whitespacesAndNewlines)
251	        switch value {
252	        case "development", "production":
253	            return value
254	        default:
255	            return nil
256	        }
257	    }
258	}
