27	#if canImport(ActivityKit)
28	@available(iOS 16.1, *)
29	private enum NinebotChargingActivityController {
30	    static func sync(with dashboard: NinebotDashboard) async {
31	        guard ActivityAuthorizationInfo().areActivitiesEnabled else {
32	            await endAll()
33	            return
34	        }
35	
36	        guard let snapshot = dashboard.primaryVehicle,
37	              snapshot.state.isCharging == true,
38	              !snapshot.state.isFullyCharged,
39	              let battery = snapshot.state.battery else {
40	            await endAll()
41	            return
42	        }
43	
44	        let attributes = NinebotChargingActivityAttributes(
45	            vehicleSN: snapshot.vehicle.sn,
46	            vehicleName: snapshot.vehicle.name,
47	            vehicleModel: snapshot.vehicle.model
48	        )
49	        let state = NinebotChargingActivityAttributes.ContentState(
50	            battery: battery,
51	            estimatedRange: snapshot.state.localEstimatedMileage ?? snapshot.state.endurance ?? snapshot.state.aiEstimatedMileage,
52	            estimatedFullAt: estimatedFullAt(for: snapshot.state),
53	            chargingPower: snapshot.state.chargingPower,
54	            batteryTemperature: snapshot.state.batteryTemperature,
55	            batteryVoltage: snapshot.state.batteryVoltage,
56	            chargingSpeed: snapshot.state.estimatedChargingSpeedKmh,
57	            updatedAt: snapshot.state.updatedAt
58	        )
59	        let content = ActivityContent(
60	            state: state,
61	            staleDate: staleDate(for: state)
62	        )
63	
64	        let activities = Activity<NinebotChargingActivityAttributes>.activities
65	        let matchingActivity = activities.first { $0.attributes.vehicleSN == snapshot.vehicle.sn }
66	        NinebotSharedStore().pruneChargingLiveActivityPushTokens(activeActivityIDs: Set(activities.map(\.id)))
67	        await MainActor.run {
68	            for activity in activities {
69	                NinebotChargingLiveActivityTokenObserver.shared.observeActivity(activity)
70	            }
71	        }
72	
73	        for activity in activities where activity.id != matchingActivity?.id {
74	            await activity.end(content, dismissalPolicy: .immediate)
75	            NinebotSharedStore().removeChargingLiveActivityPushToken(activityID: activity.id)
76	        }
77	
78	        if let matchingActivity {
79	            await matchingActivity.update(content)
80	        } else {
81	            do {
82	                let activity = try Activity.request(
83	                    attributes: attributes,
84	                    content: content,
85	                    pushType: .token
86	                )
87	                await MainActor.run {
88	                    NinebotChargingLiveActivityTokenObserver.shared.observeActivity(activity)
89	                }
90	            } catch {
91	                #if DEBUG
92	                print("Failed to start NineBot charging Live Activity: \(error)")
93	                #endif
94	            }
95	        }
96	    }
97	
98	    private static func endAll() async {
99	        for activity in Activity<NinebotChargingActivityAttributes>.activities {
100	            await activity.end(nil, dismissalPolicy: .immediate)
101	        }
102	        NinebotSharedStore().removeAllChargingLiveActivityPushTokens()
103	    }
104	
105	    private static func estimatedFullAt(for state: NinebotVehicleState) -> Date? {
106	        guard let minutes = state.estimatedFullChargeMinutes, minutes > 0 else { return nil }
107	        return Date().addingTimeInterval(minutes * 60)
108	    }
109	
110	    private static func staleDate(for state: NinebotChargingActivityAttributes.ContentState) -> Date {
111	        if let estimatedFullAt = state.estimatedFullAt, estimatedFullAt > Date() {
112	            return estimatedFullAt.addingTimeInterval(5 * 60)
113	        }
114	        return Date().addingTimeInterval(60 * 60)
115	    }
116	
117	}
