5	enum NinebotBackgroundTaskManager {
6	    static let refreshIdentifier = "com.example.NineBotPlus.refresh"
7	
8	    static func register() {
9	        BGTaskScheduler.shared.register(forTaskWithIdentifier: refreshIdentifier, using: nil) { task in
10	            guard let refreshTask = task as? BGAppRefreshTask else {
11	                task.setTaskCompleted(success: false)
12	                return
13	            }
14	            handle(refreshTask)
15	        }
16	    }
17	
18	    static func scheduleRefresh(after interval: TimeInterval = defaultRefreshInterval) {
19	        let request = BGAppRefreshTaskRequest(identifier: refreshIdentifier)
20	        request.earliestBeginDate = Date().addingTimeInterval(interval)
21	
22	        do {
23	            try BGTaskScheduler.shared.submit(request)
24	        } catch {
25	            // The system may reject duplicate or temporarily unavailable requests.
26	        }
27	    }
28	
29	    private static func handle(_ task: BGAppRefreshTask) {
30	        scheduleRefresh()
31	
32	        let operation = Task {
33	            await refreshDashboard(source: "Background")
34	        }
35	
36	        task.expirationHandler = {
37	            operation.cancel()
38	        }
39	
40	        Task {
41	            let success = await operation.value
42	            task.setTaskCompleted(success: success)
43	        }
44	    }
45	
46	    @discardableResult
47	    static func refreshDashboard(source: String) async -> Bool {
48	        let startedAt = Date()
49	        let store = NinebotSharedStore()
50	        let cached = store.loadDashboard()
51	        let configuration = store.loadConfiguration() ?? NinebotServerConfiguration(baseURLString: "", bearerToken: "")
52	
53	        guard configuration.isUsable else {
54	            store.saveLastAppRefreshEvent(NinebotRefreshEvent(
55	                source: source,
56	                operation: "后台刷新",
57	                startedAt: startedAt,
58	                endedAt: Date(),
59	                success: false,
60	                message: "未配置数据源"
61	            ))
62	            return false
63	        }
64	
65	        do {
66	            let dashboard = try await NinebotServerClient(configuration: configuration)
67	                .fetchDashboard(selectedSN: cached?.selectedSN)
68	            let archivedDashboard = store.saveDashboard(dashboard)
69	            NinebotChargingLiveActivityManager.sync(with: archivedDashboard)
70	            store.saveLastAppRefreshEvent(NinebotRefreshEvent(
71	                source: source,
72	                operation: "后台刷新",
73	                startedAt: startedAt,
74	                endedAt: Date(),
75	                success: true,
76	                message: archivedDashboard.primaryVehicle?.vehicle.name
77	            ))
78	            WidgetCenter.shared.reloadAllTimelines()
79	            return true
80	        } catch {
81	            store.saveLastError(error.localizedDescription)
82	            store.saveLastAppRefreshEvent(NinebotRefreshEvent(
83	                source: source,
84	                operation: "后台刷新",
85	                startedAt: startedAt,
86	                endedAt: Date(),
87	                success: false,
88	                message: error.localizedDescription
89	            ))
90	            return false
91	        }
92	    }
93	
94	    private static var defaultRefreshInterval: TimeInterval {
95	        let state = NinebotSharedStore().loadDashboard()?.primaryVehicle?.state
96	        if state?.isCharging == true, state?.isFullyCharged != true {
97	            return 15 * 60
98	        }
99	        if state?.isLocked == false || state?.isPoweredOn == true {
100	            return 20 * 60
101	        }
102	        return 30 * 60
103	    }
104	}
