private struct CapturePrivacyProtectionModifier: ViewModifier {
    var isEnabled: Bool
    var isObscured: Bool
    var cornerRadius: CGFloat
    var message: String?

    @ViewBuilder
    func body(content: Content) -> some View {
        if isEnabled {
            ScreenCaptureProtectedView(
                isEnabled: isEnabled,
                isObscured: isObscured
            ) {
                content
            } placeholder: {
                CapturePrivacyPlaceholder(cornerRadius: cornerRadius, message: message)
            }
            .animation(.easeInOut(duration: 0.18), value: isObscured)
        } else {
            content
        }
    }
}

private struct CapturePrivacyPlaceholder: View {
    var cornerRadius: CGFloat
    var message: String?

    var body: some View {
        if let message {
            RoundedRectangle(cornerRadius: cornerRadius, style: .continuous)
                .fill(.ultraThinMaterial)
                .overlay {
                    Label(message, systemImage: "eye.slash.fill")
                        .font(.caption.weight(.semibold))
                        .foregroundStyle(Color.teslaPrimaryText)
                        .padding(.horizontal, 12)
                        .padding(.vertical, 8)
                        .background(.regularMaterial, in: Capsule())
                }
        } else {
            Color.clear
        }
    }
}

private extension View {
    func capturePrivacyProtected(
        isEnabled: Bool,
        isObscured: Bool,
        cornerRadius: CGFloat,
        message: String? = nil
    ) -> some View {
        modifier(CapturePrivacyProtectionModifier(
            isEnabled: isEnabled,
            isObscured: isObscured,
            cornerRadius: cornerRadius,
            message: message
        ))
    }
}

